    off += 1;
    if (off + fLen > len) return;
    std::string f((const char*)body + off, fLen);
    off += fLen;
    if (off + 2 > len) return;
    uint16_t data1Len = rd16be(body, off);
    off += 2;
    if (off + data1Len > len) return;
